argv:
$ErrorActionPreference='Stop'
$base='http://127.0.0.1:17448'
function Get-Safe($path) {
  try { return Invoke-RestMethod -UseBasicParsing -Method Get -Uri ($base+$path) -TimeoutSec 15 }
  catch { return [pscustomobject]@{ endpoint=$path; error=$_.Exception.Message } }
}
$out=[ordered]@{}
$out.status=Get-Safe '/api/status'
$out.managedChats=Get-Safe '/api/supervisor-watchdog/managed-chats'
$out.assignments=Get-Safe '/api/supervisor-watchdog/agent-assignments'
$out.dryRun=Get-Safe '/api/supervisor-watchdog/agent-assignments/dry-run'
$out.inventory=Get-Safe '/api/chat-inventory'
$out | ConvertTo-Json -Depth 12 -Compress
